<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { useRoute } from 'vue-router'
import { detalleRequerimiento, guardarRequerimiento, imprimirRequerimiento, listarRequerimientos, opcionesRequerimiento, type MaterialAlmacen, type RequerimientoAlmacen, type RequerimientoLinea, type RequerimientoOptions } from '../services/requerimientosAlmacen'
const route=useRoute(),rows=ref<RequerimientoAlmacen[]>([]),options=ref<RequerimientoOptions>({materiales:[],centros_costos:[],actividades:[]}),total=ref(0),lastPage=ref(1),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),materialModal=ref(false),detail=ref<RequerimientoAlmacen|null>(null),editing=ref<number|null>(null),materialSearch=ref('')
const filters=reactive({criterio:'',fecha_desde:'',fecha_hasta:'',estado:'',page:1}),form=reactive({prioridad:'n' as 'n'|'u'|'m',inversion_id:0,informacion:'',enviar_copia:false,items:[] as RequerimientoLinea[]})
const filteredMaterials=computed(()=>{const q=materialSearch.value.toLowerCase();return options.value.materiales.filter(x=>!q||x.nombre.toLowerCase().includes(q)||x.grupo?.toLowerCase().includes(q))})
async function load(page=1){filters.page=page;loading.value=true;error.value='';try{const response=await listarRequerimientos(filters);rows.value=response.data;total.value=response.total;lastPage.value=response.last_page}catch(cause){error.value=message(cause)}finally{loading.value=false}}
async function init(){try{options.value=await opcionesRequerimiento()}catch{}await load();if(route.query.nuevo==='1')await open()}
async function open(item?:RequerimientoAlmacen){editing.value=item?.id||null;let current=item;if(item)try{current=await detalleRequerimiento(item.id)}catch{}Object.assign(form,{prioridad:current?.prioridad||'n',inversion_id:current?.inversion_id||0,informacion:current?.informacion||'',enviar_copia:false,items:current?.detalles?.map(x=>({...x}))||[]});modal.value=true}
function add(material:MaterialAlmacen){if(form.items.some(x=>x.item_id===material.id)){error.value='El material ya fue agregado.';return}form.items.push({item_id:material.id,item:material.nombre,unidad:material.unidad,saldo:material.saldo,cantidad:1,glosa:'',centro_costos_id:0,actividad_presupuestal_id:0});materialModal.value=false}
function available(line:RequerimientoLinea){return line.saldo==null||line.cantidad<=line.saldo}
async function save(){if(!form.items.length){error.value='Agregue al menos un material.';return}if(form.items.some(x=>x.cantidad<1||!x.actividad_presupuestal_id)){error.value='Complete cantidad y actividad presupuestal de todos los materiales.';return}if(form.items.some(x=>!available(x))&&!confirm('Hay cantidades mayores al stock disponible. ¿Desea continuar?'))return;saving.value=true;try{await guardarRequerimiento(editing.value,{...form,es_requerimiento_almacen:true,tipo:'m'});success.value='Requerimiento guardado correctamente.';modal.value=false;await load()}catch(cause){error.value=message(cause)}finally{saving.value=false}}
async function show(item:RequerimientoAlmacen){try{detail.value=await detalleRequerimiento(item.id)}catch(cause){error.value=message(cause)}}
function message(cause:unknown){return cause instanceof Error?cause.message:'No se pudo completar la operación.'}onMounted(init)
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Logística / Requerimientos de almacén</nav><header class="hero"><div class="mark">RA</div><div><small>MIA · Logística</small><h1>Requerimientos de almacén</h1><p>Solicita materiales de uso común considerando su stock y actividad presupuestal.</p></div><strong>{{total}} requerimientos</strong><button @click="open()">+ Nuevo requerimiento</button></header><p v-if="success" class="flash">✓ {{success}}</p><p v-if="error" class="flash error">{{error}}</p><section class="filters"><label>Glosa o código<input v-model.trim="filters.criterio" @keyup.enter="load(1)"></label><label>Desde<input v-model="filters.fecha_desde" type="date"></label><label>Hasta<input v-model="filters.fecha_hasta" type="date"></label><label>Estado<select v-model="filters.estado"><option value="">Todos</option><option value="pendiente">Pendiente</option><option value="atendido">Atendido</option><option value="anulado">Anulado</option></select></label><button @click="load(1)">Buscar</button></section><div v-if="loading" class="empty">Cargando requerimientos…</div><div v-else-if="!rows.length" class="empty">No se encontraron requerimientos.</div><section v-else class="table"><header><span>Código</span><span>Información adicional</span><span>Fecha</span><span>Prioridad</span><span>Estado</span><span>Acciones</span></header><article v-for="item in rows" :key="item.id"><b>#{{String(item.id).padStart(6,'0')}}</b><p>{{item.informacion||'Sin información adicional'}}</p><time>{{item.fecha_registro}}</time><span>{{item.prioridad==='m'?'Muy urgente':item.prioridad==='u'?'Urgente':'Normal'}}</span><em>{{item.estado_label||item.estado}}</em><footer><button @click="show(item)">Seguimiento</button><button @click="imprimirRequerimiento(item.id)">Imprimir</button><button v-if="['abierto','pendiente','0','5'].includes(String(item.estado).toLowerCase())" @click="open(item)">Editar</button></footer></article></section><footer v-if="lastPage>1" class="pages"><button :disabled="filters.page<=1" @click="load(filters.page-1)">Anterior</button><span>{{filters.page}} / {{lastPage}}</span><button :disabled="filters.page>=lastPage" @click="load(filters.page+1)">Siguiente</button></footer>
<div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="modal wide" @submit.prevent="save"><header><div><small>Requerimiento de almacén</small><h2>{{editing?'Editar':'Registrar'}} requerimiento</h2></div><button type="button" @click="modal=false">×</button></header><div class="form-grid"><label>Prioridad<select v-model="form.prioridad"><option value="n">Normal</option><option value="u">Urgente</option><option value="m">Muy urgente</option></select></label><label>Tipo de gasto<select v-model="form.inversion_id"><option :value="0">Gasto operativo</option><option :value="1">Gasto de inversión</option></select></label></div><label>Información adicional<textarea v-model.trim="form.informacion" maxlength="300" rows="3"/></label><section class="items-head"><h3>Materiales solicitados</h3><button type="button" @click="materialModal=true">+ Agregar material</button></section><div class="item-table"><header><span>Material</span><span>Cantidad</span><span>Glosa</span><span>Centro de costos</span><span>Actividad presupuestal *</span><span></span></header><article v-for="(line,i) in form.items" :key="line.item_id" :class="{over:!available(line)}"><div><b>{{line.item}}</b><small>{{line.unidad}} · Stock: {{line.saldo??'—'}}</small></div><input v-model.number="line.cantidad" type="number" min="1" step="0.01"><input v-model.trim="line.glosa"><select v-model="line.centro_costos_id"><option :value="0">Sin asignar</option><option v-for="center in options.centros_costos" :key="center.id" :value="center.id">{{center.nombre}}</option></select><select v-model="line.actividad_presupuestal_id"><option :value="0" disabled>Seleccione</option><option v-for="activity in options.actividades" :key="activity.id" :value="activity.id">{{activity.nombre}}</option></select><button type="button" @click="form.items.splice(i,1)">×</button></article></div><p v-if="!form.items.length" class="mini-empty">Agregue materiales al requerimiento.</p><label class="check"><input v-model="form.enviar_copia" type="checkbox"> Enviar copia por correo</label><footer><button type="button" class="clear" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':'Guardar requerimiento'}}</button></footer></form></div>
<div v-if="materialModal" class="backdrop top" @mousedown.self="materialModal=false"><section class="modal"><header><h2>Seleccionar material</h2><button @click="materialModal=false">×</button></header><input v-model.trim="materialSearch" placeholder="Buscar material o grupo…"><div class="materials"><button v-for="material in filteredMaterials" :key="material.id" @click="add(material)"><span><b>{{material.nombre}}</b><small>{{material.grupo}} · {{material.unidad}}</small></span><em :class="{zero:material.saldo<=0}">Stock {{material.saldo}}</em></button></div></section></div>
<div v-if="detail" class="backdrop" @mousedown.self="detail=null"><section class="modal"><header><h2>Seguimiento #{{detail.id}}</h2><button @click="detail=null">×</button></header><p>{{detail.informacion}}</p><div class="detail" v-for="line in detail.detalles" :key="line.item_id"><div><b>{{line.item}}</b><small>{{line.glosa}}</small></div><span>Solicitado: {{line.cantidad}}</span><span>Atendido: {{line.atendido||0}}</span></div></section></div></div></template>
<style scoped>
.page{--accent:#d64f83;color:#35464e}nav{margin-bottom:17px;color:#98a4aa;font-size:.7rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:22px 25px;display:flex;align-items:center;gap:15px;border-left:5px solid var(--accent);border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--accent);font-size:.65rem;font-weight:700}.hero small,.modal small{color:var(--accent);font-size:.55rem;font-weight:700}.hero h1{margin:2px 0;font-size:1.35rem}.hero p{margin:0;color:#7d898f;font-size:.7rem}.hero strong{margin-left:auto;font-size:.58rem}.hero button,.filters button,.modal footer button,.items-head button,.pages button{padding:8px 11px;border:0;border-radius:6px;color:#fff;background:var(--accent);font-size:.57rem}.flash{padding:10px;border-radius:8px;color:#286b50;background:#eff9f4;font-size:.63rem}.flash.error{color:#a13f43;background:#fff0f0}.filters{margin-top:13px;padding:12px;display:flex;align-items:end;gap:7px;border-radius:9px;background:#fff}.filters label{flex:1;font-size:.55rem}input,select,textarea{width:100%;padding:8px;border:1px solid #d8e0e4;border-radius:6px;font:inherit;font-size:.61rem}.table{margin-top:13px;border-radius:9px;background:#fff;overflow:hidden}.table>header,.table>article{padding:10px 13px;display:grid;grid-template-columns:90px 2fr 100px 80px 90px 160px;align-items:center;gap:8px}.table>header{color:#fff;background:var(--accent);font-size:.53rem;font-weight:700}.table>article{border-bottom:1px solid #edf0f2;font-size:.56rem}.table p{margin:0}.table em{padding:4px;border-radius:9px;background:#f8e9ef;font-style:normal;text-align:center}.table footer button{border:0;color:var(--accent);background:none;font-size:.52rem}.empty,.mini-empty{padding:40px;text-align:center;background:#fff;font-size:.62rem}.pages{margin-top:12px;display:flex;justify-content:center;align-items:center;gap:8px;font-size:.55rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#15283a88}.backdrop.top{z-index:110}.modal{width:min(100%,600px);max-height:90vh;overflow:auto;padding:20px;border-radius:12px;background:#fff}.modal.wide{width:min(100%,1050px)}.modal>header{display:flex}.modal h2{margin:2px 0 14px;font-size:1rem}.modal header>button{margin-left:auto;border:0;background:none;font-size:1.4rem}.modal label{display:block;margin-bottom:10px;font-size:.57rem}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.items-head{display:flex;align-items:center}.items-head button{margin-left:auto}.item-table>header,.item-table>article{display:grid;grid-template-columns:1.4fr 80px 1fr 1fr 1.3fr 25px;gap:5px;align-items:center}.item-table>header{padding:7px;color:#fff;background:#6b7580;font-size:.5rem}.item-table>article{padding:7px;border-bottom:1px solid #e8ecee}.item-table b,.item-table small{display:block;font-size:.54rem}.item-table article>button{border:0;color:#b44747;background:none}.item-table article.over{background:#fff0ed}.check input{width:auto}.modal footer{display:flex;justify-content:flex-end;gap:6px}.clear{color:#68757c!important;background:#edf1f3!important}.materials{margin-top:8px}.materials>button{width:100%;padding:10px;display:flex;border:0;border-bottom:1px solid #e8ecee;background:#fff;text-align:left}.materials span{flex:1}.materials b,.materials small{display:block;font-size:.57rem}.materials em{font-size:.53rem;font-style:normal;color:#287153}.materials em.zero{color:#b44747}.detail{padding:9px;display:flex;gap:15px;border-bottom:1px solid #e8ecee;font-size:.56rem}.detail div{flex:1}.detail small{display:block}@media(max-width:900px){.table>header,.item-table>header{display:none}.table>article,.item-table>article{grid-template-columns:1fr}.filters{align-items:stretch;flex-direction:column}.hero{flex-wrap:wrap}.hero strong{margin-left:0}}
